+ // Computes, on the calling thread, out[i] = in[0] + ... + in[i] for i < n, and
+ // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
+ // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
+ // never overflow int64.
+
+ // Global constants for block size and number of sub-histograms
+ constexpr size_t BLOCK = 512;
+ constexpr size_t SUB_K = 4;
+
+ extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+     // Zero the output histogram
+     memset(hist, 0, 256 * 8);
+
+     if (n == 0) {
+         return;
+     }
+
+     // Private sub-histograms: SUB_K independent 256‑bin counters (uint32_t)
+     alignas(64) uint32_t sub_hist[SUB_K][256] = {};
+
+     size_t i = 0;
+     int64_t total_sum = 0; // cumulative sum before current block
+
+     // Process full blocks
+     for (; i + BLOCK <= n; i += BLOCK) {
+         // Prefetch next block
+         __builtin_prefetch(in + i + BLOCK, 0, 3);
+         __builtin_prefetch(out + i + BLOCK, 1, 3);
+
+         const size_t half = BLOCK / 2;
+         int64_t sum_first = 0;
+         // First half of the block (dependency chain limited to half block)
+         for (size_t j = 0; j < half; ++j) {
+             sum_first += in[i + j];
+             out[i + j] = total_sum + sum_first;
+             uint8_t lb = static_cast<uint8_t>(in[i + j] & 255);
+             sub_hist[i & (SUB_K - 1)][lb]++;
+         }
+         int64_t sum_second = 0;
+         for (size_t j = half; j < BLOCK; ++j) {
+             sum_second += in[i + j];
+             out[i + j] = total_sum + sum_first + sum_second;
+             uint8_t lb = static_cast<uint8_t>(in[i + j] & 255);
+             sub_hist[(i + j) & (SUB_K - 1)][lb]++;
+         }
+         total_sum += sum_first + sum_second;
+     }
+
+     // Tail handling
+     int64_t tail_sum = 0;
+     for (size_t j = 0; j < n - i; ++j) {
+         tail_sum += in[i + j];
+         out[i + j] = total_sum + tail_sum;
+         uint8_t lb = static_cast<uint8_t>(in[i + j] & 255);
+         sub_hist[(i + j) & (SUB_K - 1)][lb]++;
+     }
+     total_sum += tail_sum;
+
+     // Merge private sub-histograms into the output histogram
+     for (size_t k = 0; k < SUB_K; ++k) {
+         for (size_t b = 0; b < 256; ++b) {
+             hist[b] += sub_hist[k][b];
+         }
+     }
+ }
 // OMEGA-BLOCK-END
